// GSIM gemmini FULL-SoC (ChipTop) M3 harness that actually EXECUTES a workload.
//
// The stock chipyard bootrom wfi-spins at 0x10034 waiting for a TSI IPI that never
// arrives once SerialRAM/SimTSI are pruned (GSIM_ENGINE.md 5).  Here we BAKE a
// bare-metal gemmini matmul kernel into ChipTop's combinational BootROM
// (system$bootrom_domain$bootrom$rom[512], mapped at reset vector 0x10000) so the
// Rocket core boots straight into a gemmini RoCC command stream: config_ex +
// preload + compute, DRAM-free on scratchpad (no mvin/mvout -> no DMA -> no TLB).
// The kernel image is generated by gsim_gemmini_bootrom_bake.py into
// gemmini_bootrom.h (RoCC encodings identical to the M2 stream, gsim_..._cmd_encode.py 4a).
//
// GSIM sets the rom[] constants once in an event-gated block, so overwriting the
// array persists; we (re)write it every cycle before stepping to be robust.
//
// Per cycle we read a REAL end-to-end M3 trace off the public SChipTop members:
//   * Rocket commit stage:  wb_reg_valid / wb_reg_pc / wb_reg_inst  (CPU activity)
//   * Gemmini controller FSMs: ex/load/store control_state          (accel activity)
//   * reservation-station busy, axi4_mem_0 ar/aw valid              (accel + DRAM)
// A committed custom-3 instruction (opcode 0x7b, low byte 0x7b) is a gemmini RoCC
// dispatch -- flagged in the CSV.  Feed ex/load/store into the repo occupancy
// engines (gsim_gemmini_busy_trace -> occupancy_from_busy_trace) for the waterfall.
//
// NOTE: '$' is part of the C identifier token here (clang extension); the
// hierarchical member names are spelled in full (cannot be macro-abbreviated).
#include "ChipTop.h"
#include "gemmini_bootrom.h"
#include <cstdio>
#include <cstdlib>

static void bake_bootrom(SChipTop* dut) {
  for (int i = 0; i < GEMMINI_BOOTROM_NWORDS; i++)
    dut->system$bootrom_domain$bootrom$rom[i] = GEMMINI_BOOTROM_WORDS[i];
}

int main(int argc, char** argv) {
  int run_cycles = (argc > 1) ? atoi(argv[1]) : 2000;

  SChipTop* dut = new SChipTop();

  printf("phase,cycle,commit_valid,wb_pc,wb_inst,is_rocc,"
         "gem_ex_state,gem_load_state,gem_store_state,gem_rs_busy,"
         "axi_ar_valid,axi_aw_valid\n");

  auto dump = [&](const char* phase, int c) {
    unsigned inst = (unsigned)dut->system$tile_prci_domain$element_reset_domain$rockettile$core$wb_reg_inst;
    unsigned valid = (unsigned)dut->system$tile_prci_domain$element_reset_domain$rockettile$core$wb_reg_valid;
    unsigned is_rocc = (valid && (inst & 0x7f) == 0x7b) ? 1u : 0u;  // custom-3 opcode
    printf("%s,%d,%u,0x%llx,0x%08x,%u,%u,%u,%u,%u,%u,%u\n",
      phase, c, valid,
      (unsigned long long)dut->system$tile_prci_domain$element_reset_domain$rockettile$core$wb_reg_pc,
      inst, is_rocc,
      (unsigned)dut->system$tile_prci_domain$element_reset_domain$rockettile$gemmini$ex_controller$control_state,
      (unsigned)dut->system$tile_prci_domain$element_reset_domain$rockettile$gemmini$load_controller$control_state,
      (unsigned)dut->system$tile_prci_domain$element_reset_domain$rockettile$gemmini$store_controller$control_state,
      (unsigned)dut->system$tile_prci_domain$element_reset_domain$rockettile$gemmini$reservation_station$_io_busy_T_4,
      (unsigned)dut->get_axi4_mem_0$$bits$$ar$$valid(),
      (unsigned)dut->get_axi4_mem_0$$bits$$aw$$valid());
  };

  // Running clock + reset window (bake the program while held in reset).
  dut->set_clock_uncore(1);
  dut->set_reset_io(1);
  for (int c = 0; c < 10; c++) { bake_bootrom(dut); dut->step(); }

  // Deassert reset; tie off AXI/serial slave-side readies (not back-pressured).
  dut->set_reset_io(0);
  dut->set_axi4_mem_0$$bits$$aw$$ready(1);
  dut->set_axi4_mem_0$$bits$$w$$ready(1);
  dut->set_axi4_mem_0$$bits$$ar$$ready(1);
  dut->set_serial_tl_0$$in$$valid(0);
  dut->set_serial_tl_0$$out$$ready(1);
  dut->set_custom_boot(0);

  for (int c = 0; c < run_cycles; c++) { bake_bootrom(dut); dut->step(); dump("run", c); }

  fprintf(stderr, "# total cycles stepped: %llu\n", (unsigned long long)dut->cycles);
  delete dut;
  return 0;
}
